class Account:
    def __init__(self, balance):
        self._balance = balance

    @property
    def balance(self):
        return self._balance

    def withdraw(self, amount):
        if amount > self._balance:
            raise ValueError("insufficient funds")
        self._balance -= amount

def run(start, amount):
    acc = Account(start)
    try:
        acc.withdraw(amount)
    except ValueError:
        return "refused"
    return acc.balance

